<script setup>defineProps({samples:Array,form:Object});</script><template><section class="card"><h2>音频来源</h2><label>公开示例<select v-model="form.sampleId"><option value="">选择公开示例</option><option v-for="s in samples" :value="s.id">{{s.title}}</option></select></label><div class="or">或上传音频 / 视频文件</div><input type="file" accept="audio/*,video/*" @change="form.file=$event.target.files[0]"/><div class="source-actions"><button type="button" @click="form.recording=!form.recording">{{form.recording?'停止录音':'开始麦克风录音'}}</button><input v-model="form.url" placeholder="粘贴视频链接（可选）"/></div><div class="grid-two"><label>开始时间（秒）<input v-model.number="form.start" type="number" min="0" step="0.1"/></label><label>结束时间（秒）<input v-model.number="form.end" type="number" min="0" step="0.1"/></label></div></section>
</template>